<template><q-page class="q-pa-lg"><div class="row items-center"><div><div class="page-title">Departments</div><div class="muted">Organize your people into focused teams.</div></div><q-space/><q-btn color="primary" unelevated rounded icon="add" label="Add Department" @click="open()"/></div><q-card flat bordered class="q-mt-lg"><q-table :rows="rows" :columns="columns" row-key="id" :loading="loading"><template #body-cell-actions="p"><q-td><q-btn flat round icon="edit" @click="open(p.row)"/><q-btn flat round icon="delete" color="negative" @click="remove(p.row)"/></q-td></template></q-table></q-card><q-dialog v-model="dialog"><q-card style="min-width:360px"><q-card-section class="text-h6">{{ form.id?'Edit':'Add' }} Department</q-card-section><q-card-section><q-input v-model="form.name" label="Department name" outlined/><q-input v-model="form.description" label="Description" outlined type="textarea" class="q-mt-md"/></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" v-close-popup/><q-btn color="primary" label="Save" :loading="saving" @click="save"/></q-card-actions></q-card></q-dialog></q-page></template>
<script setup>import {ref,onMounted} from 'vue';import {useQuasar} from 'quasar';import api from '../services/api';const $q=useQuasar(),rows=ref([]),loading=ref(false),saving=ref(false),dialog=ref(false),form=ref({name:'',description:''});const columns=[{name:'name',label:'Department',field:'name',align:'left'},{name:'description',label:'Description',field:'description',align:'left'},{name:'employee_count',label:'Employees',field:'employee_count'},{name:'created_at',label:'Created',field:'created_at'},{name:'actions',label:'Actions',field:'actions'}];async function load(){loading.value=true;try{rows.value=(await api.get('/departments')).data.data}finally{loading.value=false}}function open(row){form.value=row?{...row}:{name:'',description:''};dialog.value=true}async function save(){saving.value=true;try{if(form.value.id)await api.put(`/departments/${form.value.id}`,form.value);else await api.post('/departments',form.value);dialog.value=false;$q.notify({type:'positive',message:'Department saved'});load()}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Unable to save'})}finally{saving.value=false}}async function remove(row){if(!confirm(`Delete ${row.name}?`))return;try{await api.delete(`/departments/${row.id}`);$q.notify({type:'positive',message:'Department deleted'});load()}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'Unable to delete'})}}onMounted(load)</script>
